pub(super) fn positive_nodes_and_weights(order: usize) -> Option<&'static [(f64, f64)]> {
    match order {
        32 => Some(ORDER_32),
        64 => Some(ORDER_64),
        128 => Some(ORDER_128),
        256 => Some(ORDER_256),
        512 => Some(ORDER_512),
        1024 => Some(ORDER_1024),
        2048 => Some(ORDER_2048),
        _ => None,
    }
}
